function buildCumminsDetail(subject: string, language: string): string {
  const suffix = cumminsDetailTemplates[language]?.suffix || cumminsDetailTemplates.en.suffix;
  return language === 'zh' ? `${subject}，${suffix}` : `${subject} ${suffix}`;
}

export function getTranslatedCumminsSparePartDetails(name: string, language: string = 'en'): string {
  const detailKind = cumminsPartDetailKinds[name];
  if (detailKind) {
    const subject = cumminsDetailSubjects[detailKind][language] || cumminsDetailSubjects[detailKind].en;
    return buildCumminsDetail(subject, language);
  }

  return (cumminsPartDetailsTranslations.default as Record<string, string>)[language]
    || cumminsPartDetailsTranslations.default.en;
}
